package jp.personal.hanshinedge.ui;
import android.app.Activity;import android.webkit.WebView;import android.webkit.WebViewClient;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.net.*;import java.io.*;import java.nio.charset.*;import java.security.*;import java.time.*;import java.util.regex.*;import jp.personal.hanshinedge.runtime.*;import jp.personal.hanshinedge.prediction.*;
public final class RaceRepository implements AutoCloseable {
 public interface Callback {void done(JSONObject value,String error);}
 private final Activity activity;private final WebView parser;private final ExecutorService io=Executors.newSingleThreadExecutor();private boolean ready=false;private final List<Runnable> waiting=new ArrayList<>();private final AllVenueRuntime runtime;
 public static final String[] JP={"札幌","函館","福島","新潟","東京","中山","中京","京都","阪神","小倉"},EN={"SAPPORO","HAKODATE","FUKUSHIMA","NIIGATA","TOKYO","NAKAYAMA","CHUKYO","KYOTO","HANSHIN","KOKURA"};
 public RaceRepository(Activity a){activity=a;runtime=new AllVenueRuntime(a,"jra-ui",16*1024*1024);parser=new WebView(a);parser.getSettings().setJavaScriptEnabled(true);parser.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView w,String u){ready=true;for(Runnable r:new ArrayList<>(waiting))r.run();waiting.clear();}});parser.loadData("<!doctype html><title>Local inert parser</title>","text/html","UTF-8");}
 public static String asset(Activity a,String name)throws Exception{try(InputStream in=a.getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 public JSONArray historical()throws Exception{return new JSONObject(asset(activity,"jra-real-historical-fixture-20260919-20261114.json")).getJSONArray("races");}
 private void parse(String html,JSONObject meeting,Callback cb){try{String script=asset(activity,"catalog_parser.js")+"("+JSONObject.quote(html)+","+(meeting==null?"null":meeting.toString())+")";Runnable r=()->parser.evaluateJavascript(script,s->{try{JSONObject value=new JSONObject(s);cb.done(value,value.optString("error",null));}catch(Exception e){cb.done(null,"PARSER_RESULT_INVALID");}});if(ready)r.run();else waiting.add(r);}catch(Exception e){cb.done(null,e.toString());}}
 private void fetch(String cname,java.util.function.BiConsumer<String,JSONObject> ok,Callback cb){io.execute(()->{try{URL u=new URL("https://www.jra.go.jp/JRADB/accessD.html");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("User-Agent","JRA-EDGE-READONLY/1.0");c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(("CNAME="+URLEncoder.encode(cname,"UTF-8")).getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw new IOException("HTTP_"+c.getResponseCode());byte[] raw;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>4*1024*1024)throw new IOException("SOURCE_TOO_LARGE");out.write(b,0,n);}raw=out.toByteArray();}String prefix=new String(raw,StandardCharsets.ISO_8859_1),charset=prefix.toLowerCase(Locale.ROOT).contains("utf-8")?"UTF-8":"windows-31j";String html=new String(raw,Charset.forName(charset));StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(Locale.ROOT,"%02x",b&255));JSONObject receipt=new JSONObject().put("source","JRA_OFFICIAL_WEB").put("source_record_id",cname).put("raw_sha256",hash.toString()).put("source_retrieved_at",Instant.now().toString()).put("http_status",200);activity.runOnUiThread(()->ok.accept(html,receipt));}catch(Exception e){activity.runOnUiThread(()->cb.done(null,"SOURCE_UNAVAILABLE: "+e.getMessage()));}});}
 public void today(Callback cb){fetch("pw01dli00/F3",(h,proof)->parse(h,null,(value,error)->{if(error!=null){cb.done(null,error);return;}try{JSONArray all=value.getJSONArray("meetings"),today=new JSONArray();String date=LocalDate.now(ZoneId.of("Asia/Tokyo")).toString();for(int i=0;i<all.length();i++){JSONObject m=all.getJSONObject(i);int code=Integer.parseInt(m.getString("venue_code"));if(date.equals(m.getString("date"))&&code>=1&&code<=10){m.put("venue",JP[code-1]).put("venue_enum",EN[code-1]);today.put(m);}}cb.done(new JSONObject().put("meetings",today),null);}catch(Exception e){cb.done(null,e.toString());}}),cb);}
 public void races(JSONObject meeting,Callback cb){fetch(meeting.optString("cname"),(html,receipt)->{Matcher m=Pattern.compile("pw01des(?:01|10)"+meeting.optString("venue_code")+"[0-9]{16}/[A-Za-z0-9]{2}").matcher(html);if(!m.find()){cb.done(null,"CATALOG_LINK_NOT_OBSERVED");return;}String token=m.group();fetch(token,(card,proof)->parse(card,meeting,(v,e)->{if(v!=null)try{v.put("receipt",proof);}catch(Exception ignored){}cb.done(v,e);}),cb);},cb);}
 public CapabilityGate.RaceContext context(JSONObject r)throws Exception{int code=Integer.parseInt(r.getString("venue_code"));String id=r.optString("race_id","");if(id.isEmpty()||id.equals("null"))id="UNRESOLVED:"+r.optString("date")+":"+code+":"+r.optInt("race_no");return new CapabilityGate.RaceContext(id,EN[code-1],r.getInt("race_no"),r.optBoolean("obstacle"),r.optBoolean("REAL_PROSPECTIVE",false),r.optBoolean("result_known",r.optString("data_status").equals("HISTORICAL_REPLAY_ONLY")),CapabilityGate.FROZEN_MODEL);}
 public PredictionProvider.Prediction prediction(JSONObject r)throws Exception{List<FrozenMf0Engine.Input> inputs=new ArrayList<>();JSONArray runners=r.optJSONArray("runners");if(runners!=null)for(int i=0;i<runners.length();i++){JSONObject x=runners.getJSONObject(i);Double f=x.has("f0")&&!x.isNull("f0")?x.getDouble("f0"):null;Double odds=x.has("win_odds")&&!x.isNull("win_odds")?x.getDouble("win_odds"):null;inputs.add(new FrozenMf0Engine.Input(x.getInt("horse_no"),x.optString("horse_name"),odds,f));}return new PredictionProvider().predict(context(r),inputs,r.has("odds_retrieved_at")?r.getLong("odds_retrieved_at"):null,System.currentTimeMillis());}
 public JSONObject paper()throws Exception{return new JSONObject().put("starting_bankroll",100000).put("formal_records",runtime.formalBuyStatus()).put("settlement_records",runtime.settlementStatus()).put("stake_status","NOT_AVAILABLE").put("realMoney","BLOCKED");}
 @Override public void close(){io.shutdownNow();parser.destroy();runtime.close();}
}
